$pdo=db();if(!$pdo){fwrite(STDERR,"SKIP: database unavailable\n");exit(0);} $snapshot=(new WorldService($pdo))->sectorSnapshot(1);if(!in_array($snapshot['state'],['ready','empty','protected'],true))throw new RuntimeException('Unexpected Sector Map state.');foreach(['scan','cooldown','formula','states'] as $key)if(!array_key_exists($key,$snapshot))throw new RuntimeException('Missing Sector Map contract key: '.$key);$scan=$snapshot['scan'];foreach(['sensor_range','mothership_science','scan_technology','power'] as $key)if(!array_key_exists($key,$scan))throw new RuntimeException('Missing scan metric: '.$key);if($snapshot['state']==='ready'){if(!$snapshot['sector'])throw new RuntimeException('Ready sector map has no selected sector.');$last=null;foreach($snapshot['systems'] as $system){foreach(['risk_score','strategic_value','owner_signal','travel_lane','scan_status'] as $key)if(!array_key_exists($key,$system))throw new RuntimeException('Missing system scan field: '.$key);if($last!==null&&(float)$system['risk_score']>(float)$last+0.00001)throw new RuntimeException('Systems are not ordered by descending risk.');$last=$system['risk_score'];}if((int)$scan['power']!==(int)$scan['sensor_range']*max(1,(int)$scan['mothership_science'])*max(1,(int)$scan['scan_technology']))throw new RuntimeException('Scan formula mismatch.');}echo 'PASS: Sector Map scan formula, visibility, cooldown, owner signals, travel lanes, and ordered systems verified'.PHP_EOL;
